1	import {
2	  openSync,
3	  closeSync,
4	  writeSync,
5	  fsyncSync,
6	  mkdirSync,
7	  readFileSync,
8	  writeFileSync,
9	  truncateSync,
10	  renameSync,
11	  rmSync,
12	  existsSync,
13	  readdirSync,
14	  statSync,
15	} from 'node:fs';
16	import path from 'node:path';
17	import { randomUUID } from 'node:crypto';
18	
19	const LOG_NAME = 'bus.jsonl';
20	const LOG_TMP_NAME = 'bus.log.tmp';
21	const SNAPSHOT_NAME = 'bus.snapshot.json';
22	const SNAPSHOT_TMP_NAME = 'bus.snapshot.tmp';
23	// Cross-process coordination files.
24	//  - bus.lock is a short-lived mutex directory (O_EXCL mkdir) held only while
25	//    a process actually mutates the directory, so bytes from two writers can
26	//    never interleave in a file.
27	//  - bus.owner.json is the write lease. It carries the epoch credential that
28	//    increments on every takeover and the sessions holding the current lease;
29	//    a heartbeat keeps it fresh while a process is alive.
30	//  - bus.epoch is the durable high-water mark for epochs, so an epoch can
31	//    never be reused across takeovers/restarts.
32	const LOCK_NAME = 'bus.lock';
33	const OWNER_NAME = 'bus.owner.json';
34	const EPOCH_NAME = 'bus.epoch';
35	// Per-session heartbeat files (bus.hb.<sessionId>) are written WITHOUT the
36	// mutex, so a process blocked waiting for the lock still proves it is alive
37	// and is never wrongly taken over. A session whose newest heartbeat is older
38	// than LEASE_MS is dead and may be replaced.
39	const HB_PREFIX = 'bus.hb.';
40	const HB_TMP_PREFIX = 'bus.hb.tmp.';
41	// Every temp file a write uses is session-scoped under one of these
42	// prefixes, so two writers never clobber each other's tmp; stale leftovers
43	// from a crashed holder are swept under the lock on the next open.
44	const TMP_PREFIXES = [
45	  'bus.owner.tmp.',
46	  'bus.epoch.tmp.',
47	  HB_TMP_PREFIX,
48	  'bus.snapshot.tmp.',
49	  'bus.snapshot.mirror.tmp.',
50	  'bus.log.tmp.',
51	  'bus.log.reset.tmp.',
52	];
53	const envLease = Number(process.env.BUS_LEASE_MS);
54	const LEASE_MS = envLease > 0 ? envLease : 3000;
55	const envRenew = Number(process.env.BUS_RENEW_MS);
56	const RENEW_MS = envRenew > 0 ? envRenew : Math.min(250, Math.floor(LEASE_MS / 10));
57	// A mutex directory untouched for longer than this, whose owning session's
58	// heartbeat is also stale, belongs to a process that died mid-job; the next
59	// waiter breaks it.
60	const LOCK_STALE_MS = LEASE_MS;
61	const LOCK_SPIN_MS = 5;
62	const LOCK_WAIT_MS = 15000;
63	// Best-effort stats()/usage() scan: never block long behind a write job.
64	const VIEW_WAIT_MS = 100;
65	
66	// The log is a chain of segment files: the active `bus.jsonl` plus finalized
67	// `bus.<index>.jsonl` segments. Index order is oldest first; an index is
68	// never reused within the lifetime of a directory.
69	const SEGMENT_RE = /^bus\.(\d+)\.jsonl$/;
70	const segmentName = (index) => `bus.${String(index).padStart(10, '0')}.jsonl`;
71	// Multi-writer snapshots live in gen/epoch-scoped files so a preempted
72	// holder completing a stale compaction can never clobber a newer snapshot by
73	// renaming over a fixed name. The unscoped bus.snapshot.json stays readable
74	// as the legacy/canonical form (older buses and hand-crafted layouts).
75	const SNAPSHOT_SCOPED_RE = /^bus\.snapshot\.g(\d+)\.e(\d+)\.json$/;
76	const snapshotScopedName = (gen, epoch) => `bus.snapshot.g${gen}.e${epoch}.json`;
77	
78	const sleepSync = (ms) => {
79	  const slot = new Int32Array(new SharedArrayBuffer(4));
80	  Atomics.wait(slot, 0, 0, Math.max(1, ms));
81	};
82	
83	/**
84	 * Validate that `value` survives a compact JSON.stringify unchanged.
85	 * JSON silently drops undefined / functions and turns non-finite numbers
86	 * into null; the spec rejects those along with BigInt and circular
87	 * references as TypeError.
88	 */
89	function assertJsonSafe(value, stack = new Set()) {
90	  if (typeof value === 'bigint') {
91	    throw new TypeError('record contains a BigInt');
92	  }
93	  if (typeof value === 'function') {
94	    throw new TypeError('record contains a function');
95	  }
96	  if (typeof value === 'undefined') {
97	    throw new TypeError('record contains undefined');
98	  }
99	  if (typeof value === 'number' && !Number.isFinite(value)) {
100	    throw new TypeError('record contains a non-finite number');
101	  }
102	  if (value !== null && typeof value === 'object') {
103	    // Unbox boxed primitives (e.g. new Number(NaN)) before recursing.
104	    if (value instanceof Number || value instanceof String || value instanceof Boolean) {
105	      assertJsonSafe(value.valueOf(), stack);
106	      return;
107	    }
108	    if (stack.has(value)) {
109	      throw new TypeError('record contains a circular reference');
110	    }
111	    stack.add(value);
112	    if (Array.isArray(value)) {
113	      for (const item of value) assertJsonSafe(item, stack);
114	    } else {
115	      for (const key of Object.keys(value)) assertJsonSafe(value[key], stack);
116	    }
117	    stack.delete(value);
118	  }
119	}
