121	/**
122	 * Split a jsonl buffer into parsed entries. `durable` is the offset just
123	 * past the final newline; anything beyond it is a torn trailing write.
124	 */
125	function parseLog(raw) {
126	  const entries = [];
127	  let start = 0;
128	  for (let i = 0; i < raw.length; i++) {
129	    if (raw[i] === 0x0a) {
130	      if (i > start) entries.push(JSON.parse(raw.toString('utf8', start, i)));
131	      start = i + 1;
132	    }
133	  }
134	  return { entries, durable: start };
135	}
136	
137	// Finalized segments present in the directory, oldest first.
138	const listSegments = (dir) => {
139	  const out = [];
140	  for (const name of readdirSync(dir)) {
141	    const match = SEGMENT_RE.exec(name);
142	    if (match) out.push({ index: Number(match[1]), path: path.join(dir, name) });
143	  }
144	  out.sort((a, b) => a.index - b.index);
145	  return out;
146	};
147	
148	// First complete line of a log file, or null when there is none.
149	const firstEntry = (filePath) => {
150	  const raw = readFileSync(filePath);
151	  const nl = raw.indexOf(0x0a);
152	  if (nl <= 0) return null;
153	  try {
154	    return JSON.parse(raw.toString('utf8', 0, nl));
155	  } catch {
156	    return null;
157	  }
158	};
159	
160	// Highest message seq in a segment file; null when it carries no messages.
161	const segmentMaxSeq = (filePath) => {
162	  const { entries } = parseLog(readFileSync(filePath));
163	  let max = null;
164	  for (const entry of entries) {
165	    if (entry.t === 'm' && (max === null || entry.seq > max)) max = entry.seq;
166	  }
167	  return max;
168	};
169	
170	/**
171	 * Non-destructive view of the whole directory. Applies exactly the same
172	 * recovery rules the single-process opener used (snapshot anchor, truncate
173	 * checkpoint marker, committed batch brackets only, torn tails severed) but
174	 * changes nothing on disk: callers run it under the cross-process lock and
175	 * act on its result. Because every surviving fact is read from the shared
176	 * files each time, dedup keys, positions, quota occupancy and cumulative
177	 * stats are one merged state across every writer.
178	 */
179	function scanDirectory(dir) {
180	  const logPath = path.join(dir, LOG_NAME);
181	  const snapshotPath = path.join(dir, SNAPSHOT_NAME);
182	
183	  const state = {
184	    seq: 0,
185	    bytes: 0,
186	    published: 0,
187	    replayed: 0,
188	    horizon: 0,
189	    dedup: new Map(),
190	    positions: new Map(),
191	  };
192	  let snapshotGen = 0;
193	  let foldedSeq = 0;
194	  let baseMessages = [];
195	  // Surviving messages visible above the checkpoint/horizon floors, in
196	  // ascending order (retained pre-anchor segments plus the committed
197	  // suffix).
198	  const live = [];
199	  // Every accepted log-side message (same filtering as recovery), used to
200	  // recompute retained occupancy without re-parsing files.
201	  const accepted = [];
202	  // Highest epoch fenced off in this directory: complete log bytes carrying
203	  // a smaller epoch that physically follow a fence line are bytes a
204	  // preempted holder wrote after losing ownership — never mixed into state.
205	  let fenceEpoch = 0;
206	  let nextSegmentIndex = 1;
207	
208	  // Snapshot candidates are resolved AFTER the ordered log and its fence
209	  // watermark are known (see below): an anchor-less snapshot from a holder a
210	  // higher fence displaced must never become a reset basis.
211	
212	  // A line is stale only when it carries an explicit epoch stamp below the
213	  // fence watermark. Lines written before multi-writer support have no
214	  // stamp and were committed by a legitimate holder, so they always count.
215	  const epochOf = (entry) => (entry !== null && typeof entry.g === 'number' ? entry.g : 0);
216	  const isStale = (entry, watermark) =>
217	    entry !== null && typeof entry.g === 'number' && entry.g < watermark;
218	
219	  const applyEntry = (entry, watermark) => {
220	    // A line stamped with an epoch below the current fence watermark was
221	    // written by a holder that had already lost ownership: it never mixes
222	    // into counters, positions, dedup or the visible log.
223	    if (isStale(entry, watermark)) return;
224	    if (entry.t === 'm') {
225	      // At/below the horizon the message was discarded by truncation; only
226	      // its cumulative counters (carried by the marker) survive.
227	      if (entry.seq <= state.horizon) return;
228	      state.seq = entry.seq;
229	      state.bytes += entry.bytes;
230	      state.published += 1;
231	      if (typeof entry.d === 'string') {
232	        state.dedup.set(entry.d, { id: entry.id, seq: entry.seq });
233	      }
234	      const msg = { seq: entry.seq, id: entry.id, record: entry.record };
235	      live.push(msg);
236	      accepted.push(msg);
237	    } else if (entry.t === 's') {
238	      state.replayed += entry.n;
239	    } else if (entry.t === 'p') {
240	      state.positions.set(entry.name, entry.pos);
241	    }
242	  };
243	
244	  // A truncate marker is an absolute checkpoint: the cumulative counters,
245	  // positions and dedup table it carries replace whatever earlier segments
246	  // established, so recovery can start from the newest marker and ignore
247	  // everything before it.
248	  const applyMarker = (entry) => {
249	    state.seq = entry.seq;
250	    state.bytes = entry.bytes;
251	    state.published = entry.published;
252	    state.replayed = entry.replayed;
253	    state.horizon = entry.horizon;
254	    state.positions.clear();
255	    for (const [name, pos] of Object.entries(entry.positions)) state.positions.set(name, pos);
256	    state.dedup.clear();
257	    for (const [key, value] of entry.dedup) state.dedup.set(key, value);
258	  };
259	
260	  const markerLine = (gen) => JSON.stringify({ t: 'c', gen }) + '\n';
261	
262	  // Replay complete log lines and apply only the committed, non-fenced
263	  // prefix. A batch is bracketed by {t:'b',id} .. entries .. {t:'bk',id}: a
264	  // begin without its matching commit (crash mid-write, overtaken by a newer
265	  // begin, or a fence line) is severed wholesale and none of its entries
266	  // take effect. A {t:'f',e} fence raises the epoch watermark: every later
267	  // line stamped with a smaller epoch is a preempted holder's byte and is
268	  // ignored even when physically complete. The watermark lives in
269	  // `fenceState` so it carries across files in segment order. Returns the
270	  // byte offset just past the last retainable line, so torn tails and
271	  // current-epoch uncommitted tails can be truncated while fenced leftovers
272	  // stay put (logically invisible) rather than reshaping the file.
273	  // `startWatermark` is the fence watermark established by every earlier
274	  // file in segment order. It is positional, not global: history committed
275	  // before the fence line (even by the same older epoch) is legitimate and
276	  // must be retained; only bytes physically after a fence with a smaller
277	  // stamp are discarded.
278	  const recoverLog = (raw, startWatermark) => {
279	    let watermark = startWatermark;
280	    let lineStart = 0;
281	    let retainableEnd = 0;
282	    let group = null;
283	    for (let i = 0; i < raw.length; i++) {
284	      if (raw[i] !== 0x0a) continue;
285	      const entry = i > lineStart ? JSON.parse(raw.toString('utf8', lineStart, i)) : null;
286	      const completeEnd = i + 1;
287	      if (entry && entry.t === 'f') {
288	        if (epochOf(entry) > watermark) watermark = epochOf(entry);
289	        fenceEpoch = Math.max(fenceEpoch, watermark);
290	        // The fence aborts any batch a preempted holder left open.
291	        group = null;
292	        retainableEnd = completeEnd;
293	      } else if (group !== null) {
294	        if (isStale(entry, watermark)) {
295	          // Preempted holder's bytes (even a matching-looking commit) never
296	          // close or apply the current group.
297	          retainableEnd = completeEnd;
298	        } else if (entry && entry.t === 'bk' && entry.id === group.id) {
299	          for (const e of group.entries) applyEntry(e, watermark);
300	          group = null;
301	          retainableEnd = completeEnd;
302	        } else if (entry && entry.t === 'b') {
303	          // The previous group never committed; start tracking the new one.
304	          group = { id: entry.id, entries: [], beginOffset: lineStart };
305	          retainableEnd = completeEnd;
306	        } else if (entry) {
307	          group.entries.push(entry);
308	        }
309	      } else if (entry && entry.t === 'b') {
310	        if (isStale(entry, watermark)) {
311	          // A stale uncommitted group: ignore it but keep its bytes.
312	          retainableEnd = completeEnd;
313	        } else {
314	          group = { id: entry.id, entries: [], beginOffset: lineStart };
315	        }
316	      } else {
317	        if (entry) {
318	          if (entry.t === 't') applyMarker(entry);
319	          else applyEntry(entry, watermark);
320	        }
321	        retainableEnd = completeEnd;
322	      }
323	      lineStart = completeEnd;
324	    }
325	    // A current-epoch group still open at EOF is a crash/seizure mid-batch:
326	    // its bytes must be severed, so the retainable prefix ends before the
327	    // begin line (anything stale past a fence was already ignored above).
328	    if (group !== null) {
329	      return Math.min(retainableEnd, group.beginOffset);
330	    }
331	    return retainableEnd;
332	  };
333	
334	  const segments = listSegments(dir);
335	  for (const seg of segments) {
336	    if (seg.index >= nextSegmentIndex) nextSegmentIndex = seg.index + 1;
337	  }
338	  // The ordered log is every finalized segment (oldest first) followed by
339	  // the active log file.
340	  const ordered = segments.map((seg) => seg.path);
341	  if (existsSync(logPath)) ordered.push(logPath);
342	
343	  // Pending physical repairs discovered by the scan; applied by healLocked()
344	  // while the cross-process lock is held.
345	  const tails = [];
346	  const removable = [];
347	  let reset = false;
348	
349	  // Fences raise the epoch watermark in log order. Walk every file first so
350	  // each file is scanned with the watermark as of its own position and the
351	  // global maximum is known before choosing a snapshot: a fence in an
352	  // earlier segment governs later files, never earlier ones.
353	  const watermarkAtStart = [];
354	  let globalFence = 0;
355	  {
356	    let wm = 0;
357	    for (let i = 0; i < ordered.length; i++) {
358	      watermarkAtStart.push(wm);
359	      const { entries } = parseLog(readFileSync(ordered[i]));
360	      for (const entry of entries) {
361	        if (entry.t === 'f' && epochOf(entry) > wm) wm = epochOf(entry);
362	      }
363	    }
364	    globalFence = wm;
365	  }
366	
367	  // Choose the newest snapshot among the canonical file and the
368	  // gen/epoch-scoped files. Generation is primary; within one generation a
369	  // higher epoch wins, so a preempted holder finishing a stale compaction
370	  // after a takeover can never eclipse the current owner's snapshot.
371	  const snapshotCandidates = [];
372	  if (existsSync(snapshotPath)) snapshotCandidates.push({ file: snapshotPath, gen: -1, epoch: 0 });
373	  for (const name of readdirSync(dir)) {
374	    const m = SNAPSHOT_SCOPED_RE.exec(name);
375	    if (m) {
376	      snapshotCandidates.push({
377	        file: path.join(dir, name),
378	        gen: Number(m[1]),
379	        epoch: Number(m[2]),
380	      });
381	    }
382	  }
383	  snapshotCandidates.sort((a, b) =>
384	    a.gen !== b.gen ? a.gen - b.gen : a.epoch - b.epoch,
385	  );
386	
387	  const loadSnapshot = (cand) => {
388	    const snap = JSON.parse(readFileSync(cand.file, 'utf8'));
389	    snapshotGen = snap.gen;
390	    fenceEpoch = Math.max(globalFence, typeof snap.e === 'number' ? snap.e : 0);
391	    state.seq = snap.seq;
392	    state.bytes = snap.bytes;
393	    state.published = snap.published;
394	    state.replayed = snap.replayed;
395	    state.horizon = snap.horizon ?? 0;
396	    foldedSeq = snap.seq;
397	    state.dedup.clear();
398	    state.positions.clear();
399	    for (const [key, value] of snap.dedup) state.dedup.set(key, value);
400	    for (const [name, pos] of Object.entries(snap.positions)) state.positions.set(name, pos);
401	    baseMessages = snap.messages;
402	  };
403	
404	  // Resolve the usable snapshot newest-first. A candidate is usable when its
405	  // compaction completed (an anchor marker for its generation exists in the
406	  // log) or, when anchor-less, its writer's epoch is at least the current
407	  // fence watermark — i.e. the snapshot landed in its own legitimate
408	  // crash window rather than being finished by a holder a later takeover
409	  // displaced. Anchor-less candidates below the watermark are orphans: they
410	  // are removed and resolution falls back to the next-newest snapshot (whose
411	  // anchored history is still intact).
412	  let chosenSnapshot = null;
413	  let chosenHasAnchor = false;
414	  for (let k = snapshotCandidates.length - 1; k >= 0; k--) {
415	    const cand = snapshotCandidates[k];
416	    const snap = JSON.parse(readFileSync(cand.file, 'utf8'));
417	    let hasAnchor = false;
418	    for (const filePath of ordered) {
419	      const first = firstEntry(filePath);
420	      if (first && (first.t === 'c' || first.t === 't') && first.gen === snap.gen) {
421	        hasAnchor = true;
422	        break;
423	      }
424	    }
425	    if (hasAnchor || cand.epoch >= globalFence) {
426	      chosenSnapshot = cand;
427	      chosenHasAnchor = hasAnchor;
428	      loadSnapshot(cand);
429	      break;
430	    }
431	    // Displaced holder's orphaned snapshot: remove it physically.
432	    removable.push(cand.file);
433	  }
434	  // Scoped snapshots from older generations are superseded: their contents
435	  // live in the chosen snapshot and the anchored log, so reclaim them
436	  // rather than letting every compaction pile files up forever.
437	  if (chosenSnapshot) {
438	    for (const cand of snapshotCandidates) {
439	      if (cand === chosenSnapshot) continue;
440	      if (cand.file === snapshotPath) continue;
441	      if (cand.gen < snapshotGen) removable.push(cand.file);
442	    }
443	  }
444	  fenceEpoch = Math.max(fenceEpoch, globalFence);
445	
446	  // The anchor position for the chosen snapshot generation. A generation-0
447	  // truncate marker anchors even when no snapshot file exists.
448	  let startAt = -1;
449	  for (let i = 0; i < ordered.length; i++) {
450	    const first = firstEntry(ordered[i]);
451	    if (first && (first.t === 'c' || first.t === 't') && first.gen === snapshotGen) {
452	      startAt = i;
453	    }
454	  }
455	
456	  if (chosenSnapshot && !chosenHasAnchor) {
457	    // Snapshot rename landed but the log reset did not: every byte still on
458	    // disk is already folded into the snapshot. Recovery deletes the
459	    // segments and resets to a marker-led log. The orphan rule above
460	    // prevents a displaced holder's late snapshot from triggering this.
461	    reset = true;
462	    for (const seg of segments) removable.push(seg.path);
463	  } else {
464	    // Replay the live suffix starting at THIS file's positional watermark
465	    // (a fence in a later file must not retroactively invalidate history
466	    // committed before it). Torn tails / uncommitted batch tails are
467	    // remembered for physical severing rather than truncated during read.
468	    for (let i = Math.max(startAt, 0); i < ordered.length; i++) {
469	      const raw = readFileSync(ordered[i]);
470	      const committedEnd = recoverLog(raw, watermarkAtStart[i]);
471	      if (committedEnd < raw.length) tails.push({ path: ordered[i], length: committedEnd });
472	    }
473	    // Segments before the anchor whose content is folded into the snapshot
474	    // or at/below the truncation horizon can go. Segments a consumer still
475	    // needs (above the horizon) stay untouched and stay readable; their
476	    // messages still pass the fence filter as of that segment's position.
477	    for (let i = 0; i < startAt; i++) {
478	      const max = segmentMaxSeq(ordered[i]);
479	      if (max === null || max <= foldedSeq || max <= state.horizon) {
480	        removable.push(ordered[i]);
481	      } else {
482	        const floor = Math.max(state.horizon, foldedSeq);
483	        const { entries } = parseLog(readFileSync(ordered[i]));
484	        let wm = watermarkAtStart[i];
485	        for (const entry of entries) {
486	          if (entry.t === 'f') {
487	            if (epochOf(entry) > wm) wm = epochOf(entry);
488	            continue;
489	          }
490	          if (entry.t === 'm' && entry.seq > floor && !isStale(entry, wm)) {
491	            const msg = { seq: entry.seq, id: entry.id, record: entry.record };
492	            live.push(msg);
493	            accepted.push(msg);
494	          }
495	        }
496	      }
497	    }
498	  }
499	  live.sort((a, b) => a.seq - b.seq);
500	
501	  // Retained occupancy is exactly the retained messages: snapshot survivors
502	  // above the horizon plus the accepted log-side messages collected above.
503	  // Torn tails, uncommitted batches and fenced stale bytes never count.
504	  let usageBytes = 0;
505	  for (const m of baseMessages) {
506	    if (m.seq > state.horizon) usageBytes += Buffer.byteLength(JSON.stringify(m.record), 'utf8');
507	  }
508	  for (const m of accepted) {
509	    if (m.seq > state.horizon) usageBytes += Buffer.byteLength(JSON.stringify(m.record), 'utf8');
510	  }
511	
512	  return {
513	    ...state,
514	    usageBytes,
515	    snapshotGen,
516	    foldedSeq,
517	    baseMessages,
518	    live,
519	    nextSegmentIndex,
520	    fenceEpoch,
521	    markerLine,
522	    tails,
523	    removable,
524	    reset,
525	  };
526	}
527	
528	// Messages with seq > pos that survived truncation, snapshot first then the
529	// live suffix, ascending. A position below the truncation horizon starts at
530	// the earliest surviving message: the gap is already truncated. Log-side
531	// messages at/below foldedSeq are covered by the snapshot and skipped.
532	const messagesAfter = (st, pos) => {
533	  const floor = Math.max(pos, st.horizon);
534	  const out = [];
535	  for (const m of st.baseMessages) {
536	    if (m.seq > floor) {
537	      // Snapshot messages are shared in-memory objects; hand out a copy so
538	      // callers cannot mutate replay/read results for later calls.
539	      out.push({ seq: m.seq, id: m.id, record: structuredClone(m.record) });
540	    }
541	  }
542	  const logFloor = Math.max(floor, st.foldedSeq);
543	  for (const m of st.live) {
544	    if (m.seq > logFloor) {
545	      out.push({ seq: m.seq, id: m.id, record: structuredClone(m.record) });
546	    }
547	  }
548	  return out;
