33	// A bus living in a child process, driven over line-delimited JSON.
34	class Worker {
35	  constructor(dir, env = {}) {
36	    this.child = spawn(process.execPath, [WORKER], {
37	      stdio: ['pipe', 'pipe', 'inherit'],
38	      env: { ...process.env, ...env, BUS_DIR: dir },
39	    });
40	    this.nextId = 1;
41	    this.pendingReqs = new Map();
42	    this.buf = '';
43	    this.child.stdout.setEncoding('utf8');
44	    this.child.stdout.on('data', (chunk) => {
45	      this.buf += chunk;
46	      let idx;
47	      while ((idx = this.buf.indexOf('\n')) >= 0) {
48	        const line = this.buf.slice(0, idx);
49	        this.buf = this.buf.slice(idx + 1);
50	        if (!line) continue;
51	        const msg = JSON.parse(line);
52	        const settle = this.pendingReqs.get(msg.id);
53	        if (settle) {
54	          this.pendingReqs.delete(msg.id);
55	          settle(msg);
56	        }
57	      }
58	    });
59	    this.child.on('exit', () => {
60	      for (const settle of this.pendingReqs.values()) {
61	        settle({ error: 'Error', message: 'worker exited' });
62	      }
63	      this.pendingReqs.clear();
64	    });
65	    workers.push(this);
66	  }
67	
68	  call(op, params = {}) {
69	    const id = this.nextId++;
70	    return new Promise((resolve, reject) => {
71	      this.pendingReqs.set(id, (msg) => {
72	        if (msg.error) {
73	          const Ctor = ERROR_CTORS[msg.error] || Error;
74	          reject(new Ctor(msg.message));
75	        } else {
76	          resolve(msg.value);
77	        }
