  assert.deepEqual(segmentFiles(dir), ['bus.0000000002.jsonl']);
  // Dedup and positions from the marker are live.
  assert.deepEqual(await bus.publish({ i: 99, dedupKey: 'k1' }), { id: 'id-1', seq: 1 });
