        group = { id: entry.id, entries: [], beginOffset: lineStart };
      } else if (entry) {
        group.entries.push(entry);
      }
    } else if (entry && entry.t === 'b') {
      if (isStaleEntry(entry, watermark)) {
        // A stale uncommitted group: ignore it but keep its bytes.
      } else {
        group = { id: entry.id, entries: [], beginOffset: lineStart };
