  for (let r = 0; r < reqs.length; r++) {
    const req = reqs[r];
    for (const [key, reservation] of req.reservations) {
      const map = req.kind === 'single' ? pending : groupPending;
      if (map.get(key) === reservation) map.delete(key);
      if (outcome === 'ok') {
