// Build one writer request's promise/reservation bookkeeping.
const makeWriterRequest = (kind, prepared) => {
  const reservations = new Map();
  let resolveResult;
  let rejectResult;
  const promise = new Promise((resolve, reject) => {
    resolveResult = resolve;
    rejectResult = reject;
  });
  const req = { kind, prepared, reservations, resolve: resolveResult, reject: rejectResult, promise };
  // Reserve this request's first-occurrence keys at call time, mirroring
  // the committed first-acknowledgement rule for concurrent resends.
  for (const item of prepared) {
    const key = item.dedupKey;
    if (key === undefined || reservations.has(key)) continue;
    if (dedup.has(key) || pending.has(key) || groupPending.has(key)) continue;
    const reservation = { promise, resolve: resolveResult, reject: rejectResult };
    // A batch with no racer can reject this coordination promise when the
    // bus closes before the job runs; swallow that branch locally.
    if (kind === 'batch') promise.catch(() => {});
    reservations.set(key, reservation);
    if (kind === 'single') pending.set(key, reservation);
    else groupPending.set(key, reservation);
  }
  return req;
};

