// Mutating entry point: reconcile, then physically heal anything the
// scan/delta found (torn tails, leftovers of an interrupted
// compact/truncate) and rebuild the view when healing moved bytes. The
// common healthy append costs only the metadata fingerprint plus a
// positional read of bytes added since the last job.
const prepareMutationLocked = () => {
  reconcileLocked();
  let st = view.st;
  let needsHeal =
    view.tornLength !== null || st.tails.length > 0 || st.removable.length > 0 || st.reset;
  if (needsHeal) {
    if (view.tornLength !== null) {
      st.tails.push({ path: logPath, length: view.tornLength });
    }
    healLocked(st);
    seedFromScanLocked(fingerprintLocked());
    st = view.st;
    // A tail that survives the heal is re-reported by the fresh scan; a
    // later mutating job retries. Nothing is appended onto it here.
  }
  return st;
};

