    return seedFromScanLocked(fp);
  }

  const structural = fp.value !== view.fp.value;
  const activeShrank = !view.activeMissing && fp.activeSize < view.activeConsumed;
  const activeAppeared = view.activeMissing && fp.activeSize >= 0;

