const planRequest = (req, ctx) => {
  const items = req.prepared.map((item) => {
    const key = item.dedupKey;
    if (key !== undefined) {
      const hist = ctx.st.dedup.get(key);
      if (hist) {
        const reuse = { id: hist.id, seq: hist.seq };
        ctx.keyAcks.set(key, reuse);
        return { reuse };
      }
      const earlier = ctx.owned.get(key);
      if (earlier) return { reuse: earlier };
    }
    ctx.nextSeq += 1;
    const id = randomUUID();
    const ack = { id, seq: ctx.nextSeq };
    const entry = { t: 'm', seq: ack.seq, id, bytes: item.size, g: epoch, record: JSON.parse(item.recordJson) };
    if (key !== undefined) entry.d = key;
    // Persist exactly the serialized bytes `size` counted.
    let line = `{"t":"m","seq":${ack.seq},"id":${JSON.stringify(id)},"bytes":${item.size},"g":${epoch}`;
    if (key !== undefined) line += `,"d":${JSON.stringify(key)}`;
    line += `,"record":${item.recordJson}}\n`;
    if (key !== undefined) {
      ctx.owned.set(key, ack);
      ctx.keyAcks.set(key, ack);
    }
    ctx.plannedBytes += item.size;
    ctx.effectives.push({ ack, size: item.size, key, line, entry });
    return { effective: ack };
  });
  ctx.itemsByRequest.push(items);
};

// Settle every request in a merged group, plus the dedup reservations its
// requests registered at call time (which concurrent resends attach to).
// All acknowledgements come from the planner's key->ack table; requests
// themselves receive their per-record acks in input order.
const settleGroupWithKeyAcks = (reqs, ctx) => {
  for (const req of reqs) {
    for (const [key, reservation] of req.reservations) {
      const map = req.kind === 'single' ? pending : groupPending;
      if (map.get(key) === reservation) map.delete(key);
      reservation.resolve(ctx.keyAcks.get(key));
    }
  }
  for (let r = 0; r < reqs.length; r++) {
    const req = reqs[r];
    const items = ctx.itemsByRequest[r];
    const acks = items.map((item) => (item.reuse ? item.reuse : item.effective));
    req.resolve(req.kind === 'single' ? acks[0] : acks);
  }
};

// Reject a group (takeover, IO/flush failure, quota, close): release its
// reservations and fail every request. State was never applied.
const failGroup = (reqs, err) => {
  for (const req of reqs) {
    for (const [key, reservation] of req.reservations) {
      const map = req.kind === 'single' ? pending : groupPending;
      if (map.get(key) === reservation) map.delete(key);
      reservation.reject(err);
    }
    req.reject(err);
  }
};

