{
  const a={a:1}, b={b:22};
  const bus=mk(sz(a)+sz(b));
  const rs=await Promise.allSettled([bus.publish(a),bus.publish(b),bus.publish({c:333})]);
  console.log('case1', rs.map(r=>r.status==='fulfilled'?('ok'+r.value.seq):r.reason.constructor.name));
