for (let round=0; round<15; round++){
  const dir = path.join(os.tmpdir(),'mst-'+Math.random());
  mkdirSync(dir,{recursive:true});
  const N=3, PER=40;
  const procs=[];
  for(let w=0;w<N;w++){
    const p=spawn(process.execPath,[WORKER],{stdio:['pipe','pipe','inherit'],env:{...process.env,BUS_DIR:dir}});
    p._n=0;p._m=new Map();let buf='';
    p.stdout.setEncoding('utf8');
    p.stdout.on('data',c=>{buf+=c;let i;while((i=buf.indexOf('\n'))>=0){const l=buf.slice(0,i);buf=buf.slice(i+1);const m=JSON.parse(l);const s=p._m.get(m.id);if(s){p._m.delete(m.id);s(m)}}});
    p._call=(op,params={})=>new Promise((res,rej)=>{const id=++p._n;p._m.set(id,m=>m.error?rej(new Error(m.message)):res(m.value));p.stdin.write(JSON.stringify({id,op,...params})+'\n')});
    procs.push(p);
  }
  const jobs=[];
  for(let w=0;w<N;w++)for(let i=0;i<PER;i++){
    if(i%3===0) jobs.push(procs[w]._call('publishBatch',{records:[{w,i,j:0},{w,i,j:1,dedupKey:`k${w}-${i}`}]}));
    else jobs.push(procs[w]._call('publish',{record:{w,i}}));
    if(i%10===0) jobs.push(procs[(w+1)%N]._call('compact'));
    if(i%13===0) jobs.push(procs[(w+2)%N]._call('truncate',{before:i}));
  }
  const results=await Promise.all(jobs);
  // expected effective total = singles + 2 per batch
  const total = N*( (PER - Math.ceil(PER/3))*1 + Math.ceil(PER/3)*2 );
  const acks=results.filter(a=>Array.isArray(a)?true:(a&&typeof a.seq==='number'))
    .flatMap(a=>Array.isArray(a)?a:[a]);
  const seqs=acks.map(a=>a.seq).sort((x,y)=>x-y);
  let ok=seqs.length===total;
  for(let i=0;i<seqs.length;i++) if(seqs[i]!==i+1) ok=false;
  for(const p of procs) await p._call('close');
  // reopen check
  const v=await new Promise((res)=>{
