  fd = openSync(logPath, 'a');
  const writeBuffer = (buf) => {
    let off = 0;
    while (off < buf.length) {
      const written = writeSync(fd, buf, off, buf.length - off);
      if (!Number.isInteger(written) || written <= 0) {
        throw new Error('commit group: write made no progress');
      }
      off += written;
